// DMA_FIX: match the PSP port's writeback EXACTLY — it boots Rez and this
// is the one place our post-DMA register state diverged from it:
//   * Set TE (transfer end) so a driver polling completion sees it.
//   * Do NOT clear DE. On real SH4 a finished channel is DE=1,TE=1 — DE is
//     not auto-cleared. The legacy `DE=0` made a handler that checks
//     "channel enabled AND done" see "not enabled" and refuse to chain the
//     next transfer, so the batch stalled after entry0 (Rez: ta frozen at
//     1825).
//   * Do NOT write DMAC_SAR[2]. PSP leaves it at the guest-programmed
//     value; the game does not rely on it advancing.
//   * SB_C2DSTAT is the *destination* (TA FIFO); leave it untouched on the
//     TA path (only the 32-bit texture path advances it, above) instead
//     of clobbering it with src.

if (get_gdrom_stat_fix_preset())
{
    // GDROM_STAT_FIX (Flycast gd_get_subcode format 1, flycastPS3
    // 3.3b): the block above starts DATA-Q at [5] and writes 0x14 a
    // second time, so every later byte is one late, and sz=12 cuts the
    // absolute FAD. 14 bytes, Q data right after the length; track,
    // ctrl/ADR and the elapsed FADs from the TOC.
    const u32 fad = gd_report_fad();
    u32 tstart;
    u8  ctrl_adr;
    const u32 track = libGDR_GetTrackForFAD(fad, &tstart, &ctrl_adr);
    const u32 elapsed = fad - tstart;
    subc_info[2]=0;
    subc_info[3]=0xE;
    subc_info[4]=ctrl_adr;
    subc_info[5]=(u8)track;
    subc_info[6]=1;                 // index
    subc_info[7]=(u8)(elapsed>>16);
    subc_info[8]=(u8)(elapsed>>8);
    subc_info[9]=(u8)elapsed;
    subc_info[10]=0;
    subc_info[11]=(u8)(fad>>16);
    subc_info[12]=(u8)(fad>>8);
    subc_info[13]=(u8)fad;
    sz = alloc_len < 14 ? alloc_len : 14;
}
