    input  [2:0]  texu,         // TSP.TexU
    input  [2:0]  texv,         // TSP.TexV
    input  [3:0]  miplevel,     // selected mip level (0 = base; 0..TexU+3)
    input  [4:0]  text_ctrl,    // TEXT_CONTROL&31 (stride unit)
