reg [2:0]  i1_pixfmt; reg [1:0] i1_palfmt; reg i1_scan, i1_twid; reg [5:0] i1_palsel;
reg [7:0]  i1_uf, i1_vf; reg [1:0] i1_filt; reg i1_igna, i1_tex; reg [IDW-1:0] i1_id;
