{
    if (CurrentMsgItem==null) CreateEventRow();
    CurrentMsgItem.Text=Buffer.ToString();

    // if null, a new row will be created next time this function is called
    if (CreateRowNextTime==true) CurrentMsgItem=null;

    dx.init(this.screen);
}

